import Link from 'next/link'
import { prisma } from '@/lib/prisma'
import { Product, ProductVariant } from '@prisma/client'
import HomeWrapper from '@/components/HomeWrapper' // Assuming this path for the new client component

export default function HomePage() {
  return (
    <HomeServerFetcher />
  )
}

async function HomeServerFetcher() {
  const products = await prisma.product.findMany({
    orderBy: { createdAt: 'desc' },
    include: { variants: true }
  })

  // We need to serialize the Decimal types for client components
  const serializedProducts = products.map(p => ({
    ...p,
    variants: p.variants.map(v => ({
      ...v,
      price: v.price.toString(),
      dimensions: v.dimensions
    })),
    createdAt: p.createdAt.toISOString(),
    updatedAt: p.updatedAt.toISOString()
  }))

  return <HomeWrapper products={serializedProducts} />
}
